<?php require_once __DIR__ . '/../../includes/functions.php'; require_admin(); $bookings=db()->query('SELECT b.*, c.title AS car_title FROM bookings b LEFT JOIN cars c ON c.id=b.car_id ORDER BY b.id DESC')->fetchAll(); ?><!DOCTYPE html><html><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width, initial-scale=1.0"><title>Bookings</title><link rel="stylesheet" href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css"><link rel="stylesheet" href="/car-rent-sale-system/assets/css/style.css"></head><body class="dashboard-wrapper"><div class="container-fluid"><div class="row"><?php include __DIR__ . '/../includes/sidebar.php'; ?><div class="col-lg-10 p-4"><h1 class="mb-4">Bookings</h1><div class="table-wrap"><table class="table"><thead><tr><th>ID</th><th>Customer</th><th>Car</th><th>Dates</th><th>Amount</th><th>Status</th></tr></thead><tbody><?php foreach($bookings as $row): ?><tr><td><?= (int)$row['id']; ?></td><td><?= e($row['customer_name']); ?><br><small><?= e($row['phone']); ?></small></td><td><?= e($row['car_title'] ?? 'N/A'); ?></td><td><?= e($row['pickup_date']); ?> to <?= e($row['return_date']); ?></td><td>$<?= e($row['total_amount']); ?></td><td><?= e($row['booking_status']); ?></td></tr><?php endforeach; ?></tbody></table></div></div></div></div></body></html>
